#include <Servo.h>
Servo radarServo;
const int trigPin = 9;
const int echoPin = 10;
const int servoPin = 6;
long duration;
float distanceCm;
float getDistance() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  duration = pulseIn(echoPin, HIGH, 30000);
  if (duration == 0) return -1;
  distanceCm = (duration * 0.0343) / 2.0;
  return distanceCm;
}
void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  radarServo.attach(servoPin);
  Serial.begin(9600);
  radarServo.write(90);
  delay(500);
}
void loop() {
  for (int angle = 15; angle <= 165; angle++) {
    radarServo.write(angle);
    delay(20);
    float d = getDistance();
    Serial.print(angle);
    Serial.print(",");
    Serial.println(d);
    delay(15);
  }
  for (int angle = 165; angle >= 15; angle--) {
    radarServo.write(angle);
    delay(20);
    float d = getDistance();
    Serial.print(angle);
    Serial.print(",");
    Serial.println(d);
    delay(15);
  }
}
